import{_ as s,I as t,c as d,o as h,j as i,ap as r,a as l,J as n}from"./chunks/framework.BVMg0REN.js";const f=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"FAQ/index.md","filePath":"zh/FAQ/index.md","lastUpdated":1780047210000}'),o={name:"FAQ/index.md"},c={id:"常见问题",tabindex:"-1"};function k(p,a,b,u,g,m){const e=t("Badge");return h(),d("div",null,[i("h1",c,[a[0]||(a[0]=l("常见问题")),n(e,{type:"danger",text:"必读"}),a[1]||(a[1]=l()),a[2]||(a[2]=i("a",{class:"header-anchor",href:"#常见问题","aria-label":"Permalink to “常见问题”"},"​",-1))]),a[3]||(a[3]=r(`<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>第一次使用 MaaYuan 时，建议先看 <a href="./../Started/Install.html">下载与安装</a> 与 <a href="./../Started/FirstLaunch.html">首次启动</a>。如果还是有问题，再来查这份 FAQ。</p></div><h2 id="一、不会处理时先做什么" tabindex="-1">一、不会处理时先做什么 <a class="header-anchor" href="#一、不会处理时先做什么" aria-label="Permalink to “一、不会处理时先做什么”">​</a></h2><ol><li>先确认 MaaYuan 是否为最新版本。</li><li>优先检查运行库、分辨率、触控方式和连接地址。</li><li>导出 <code>debug/maa.log</code> 后再反馈。</li><li>如果只是想先快速定位，也可以把日志交给 AI 辅助分析。</li></ol><h2 id="二、下载-安装问题" tabindex="-1">二、下载 / 安装问题 <a class="header-anchor" href="#二、下载-安装问题" aria-label="Permalink to “二、下载 / 安装问题”">​</a></h2><h3 id="下载哪个安装包" tabindex="-1">下载哪个安装包 <a class="header-anchor" href="#下载哪个安装包" aria-label="Permalink to “下载哪个安装包”">​</a></h3><ul><li>目前只支持两种安装包：<code>MaaYuan-win-x86_64-vXXX.zip</code> 与 <code>MaaYuan-macos-aarch64-vXXX.tar.gz</code></li><li>Windows 仅支持 <code>x64</code>，不支持 Windows ARM</li><li>macOS 仅支持 Apple Silicon（<code>aarch64</code>），不支持 Intel Mac</li><li>Linux、Android、iOS 与其他未知平台当前均不支持</li></ul><h3 id="运行库问题" tabindex="-1">运行库问题 <a class="header-anchor" href="#运行库问题" aria-label="Permalink to “运行库问题”">​</a></h3><ul><li>先确认是否已安装正确的 <code>.NET 10</code> 运行库</li><li>Windows 可能还需要补装 <code>VCRedist</code></li></ul><h3 id="系统问题" tabindex="-1">系统问题 <a class="header-anchor" href="#系统问题" aria-label="Permalink to “系统问题”">​</a></h3><ul><li>不支持 <code>32</code> 位系统</li><li>不支持 <code>Windows 7 / 8 / 8.1</code></li><li>若系统组件损坏，可能只能重装系统</li></ul><h3 id="更新版本出现问题" tabindex="-1">更新版本出现问题 <a class="header-anchor" href="#更新版本出现问题" aria-label="Permalink to “更新版本出现问题”">​</a></h3><ol><li>彻底关闭 MaaYuan。</li><li>打开任务管理器结束所有 <code>adb</code> 进程。</li><li>仍失败时，直接删除旧版本并解压最新完整包。</li></ol><h2 id="三、启动问题" tabindex="-1">三、启动问题 <a class="header-anchor" href="#三、启动问题" aria-label="Permalink to “三、启动问题”">​</a></h2><h3 id="常见报错与对应方向" tabindex="-1">常见报错与对应方向 <a class="header-anchor" href="#常见报错与对应方向" aria-label="Permalink to “常见报错与对应方向”">​</a></h3><table tabindex="0"><thead><tr><th>报错</th><th>优先处理方向</th></tr></thead><tbody><tr><td><code>MFA 遇到了问题</code></td><td>先回看运行库与系统环境</td></tr><tr><td><code>无法加载 DLL</code></td><td>确认在解压后的原目录中运行</td></tr><tr><td><code>此应用无法在你的电脑上运行</code></td><td>多半是下错架构包</td></tr><tr><td><code>XX 异常</code></td><td>常见于 <code>.NET</code> 运行库不完整</td></tr><tr><td><code>未能加载文件</code></td><td>系统版本过旧</td></tr><tr><td><code>检测资源...错误</code></td><td>检查网络、DNS 或相关代理工具</td></tr></tbody></table><h3 id="启动-agent-无进展" tabindex="-1">启动 Agent 无进展 <a class="header-anchor" href="#启动-agent-无进展" aria-label="Permalink to “启动 Agent 无进展”">​</a></h3><ul><li>常见原因是仍在安装依赖库，请先等一会儿。</li><li>如果长时间无进展： <ul><li>重启再试</li><li>重新下载完整包</li><li>使用“重新下载资源全量包”</li><li>Mac 用户优先排查系统安全限制</li></ul></li></ul><h3 id="依赖安装失败" tabindex="-1">依赖安装失败 <a class="header-anchor" href="#依赖安装失败" aria-label="Permalink to “依赖安装失败”">​</a></h3><p>可改为手动安装，示例命令形如：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">D:\\MaaYuan-win-x86_64-v0.9.13-beta.7\\python\\python.exe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maafw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pandas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openpyxl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loguru</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> opencv-python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zhconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pypi.tuna.tsinghua.edu.cn/simple</span></span></code></pre></div><p>如果镜像不可用，可替换为其他源，例如：</p><div class="language-txt"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://mirrors.aliyun.com/pypi/simple</span></span></code></pre></div><h2 id="四、连接错误" tabindex="-1">四、连接错误 <a class="header-anchor" href="#四、连接错误" aria-label="Permalink to “四、连接错误”">​</a></h2><h3 id="基础检查" tabindex="-1">基础检查 <a class="header-anchor" href="#基础检查" aria-label="Permalink to “基础检查”">​</a></h3><ol><li>先自行安装并打开模拟器。</li><li>关闭模拟器后台保活。</li><li>更新到较新的模拟器版本。</li><li>先手动进入游戏并停在可见头像与昵称的页面，再打开 MaaYuan。</li></ol><h3 id="adb-被占用或连接不上" tabindex="-1"><code>ADB</code> 被占用或连接不上 <a class="header-anchor" href="#adb-被占用或连接不上" aria-label="Permalink to “ADB 被占用或连接不上”">​</a></h3><ul><li>关闭手机助手及类似后台</li><li>检查是否被其他 MaaYuan 或游戏实例占用</li><li>在任务管理器里结束所有 <code>adb</code> 相关进程</li></ul><h3 id="端口被占用怎么查" tabindex="-1">端口被占用怎么查 <a class="header-anchor" href="#端口被占用怎么查" aria-label="Permalink to “端口被占用怎么查”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5037</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aon</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findstr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5555</span></span></code></pre></div><p>找到末尾的 <code>PID</code> 后，可在任务管理器中定位并结束可疑进程。</p><h3 id="自动连接检测失败" tabindex="-1">自动连接检测失败 <a class="header-anchor" href="#自动连接检测失败" aria-label="Permalink to “自动连接检测失败”">​</a></h3><ul><li>先尝试以管理员权限启动 MaaYuan</li><li>仍失败就改用手动设置</li><li>自定义连接时确认 <code>ADB</code> 路径、端口和地址完全正确</li></ul><h3 id="自定义连接建议" tabindex="-1">自定义连接建议 <a class="header-anchor" href="#自定义连接建议" aria-label="Permalink to “自定义连接建议”">​</a></h3><ol><li>下载 <code>platform tools</code> 并解压到全英文路径。</li><li>在 MaaYuan 中手动导入 <code>adb.exe</code>。</li><li>手动填写连接地址。</li><li>用自定义连接时不要再点“刷新”。</li></ol><h2 id="五、运行问题" tabindex="-1">五、运行问题 <a class="header-anchor" href="#五、运行问题" aria-label="Permalink to “五、运行问题”">​</a></h2><h3 id="运行任务后无反应或一直乱点" tabindex="-1">运行任务后无反应或一直乱点 <a class="header-anchor" href="#运行任务后无反应或一直乱点" aria-label="Permalink to “运行任务后无反应或一直乱点”">​</a></h3><ul><li>重启 MaaYuan</li><li>检查多开端口是否对应正确实例</li><li>关闭后台保活</li><li>确认分辨率为 <code>720 × 1280</code></li><li>切换触控方式重试</li></ul><h3 id="_6-24-7-15-失败" tabindex="-1"><code>6-24 / 7-15</code> 失败 <a class="header-anchor" href="#_6-24-7-15-失败" aria-label="Permalink to “6-24 / 7-15 失败”">​</a></h3><ul><li>先确认分辨率</li><li>确认已解锁相关章节并停在正确入口</li><li><code>MuMu</code> 用户记得关闭后台保活</li><li><code>DPI</code> 建议不低于 <code>180</code></li><li>必要时关闭 GPU 加速</li></ul><h3 id="截图耗时过长-触控慢" tabindex="-1">截图耗时过长 / 触控慢 <a class="header-anchor" href="#截图耗时过长-触控慢" aria-label="Permalink to “截图耗时过长 / 触控慢”">​</a></h3><ul><li>截图用时 <code>≤1000ms</code> 通常属于正常范围</li><li>可以尝试 GPU 加速推理</li><li>但老旧显卡或核显不建议强开</li></ul><h3 id="启动游戏无法运行" tabindex="-1">启动游戏无法运行 <a class="header-anchor" href="#启动游戏无法运行" aria-label="Permalink to “启动游戏无法运行”">​</a></h3><ul><li>根据游戏语言选择正确资源类型</li><li>港服务必确认语言与客户端版本是否对应</li><li>如果只是手动开游戏，不一定非要勾选“启动游戏”任务</li></ul><h2 id="六、作业问题" tabindex="-1">六、作业问题 <a class="header-anchor" href="#六、作业问题" aria-label="Permalink to “六、作业问题”">​</a></h2><h3 id="资源加载失败" tabindex="-1">资源加载失败 <a class="header-anchor" href="#资源加载失败" aria-label="Permalink to “资源加载失败”">​</a></h3><ul><li>作业文件要放在 <code>resource\\copilot-cache</code></li><li>推荐优先使用神秘代码导入</li><li>删除有问题的作业后重启，如仍异常可直接更新到最新版本</li></ul><h3 id="神秘代码导入失败" tabindex="-1">神秘代码导入失败 <a class="header-anchor" href="#神秘代码导入失败" aria-label="Permalink to “神秘代码导入失败”">​</a></h3><ul><li>多数情况是网络问题</li><li>可稍后重试，或改为下载 <code>JSON</code> 本地导入</li></ul><h3 id="抄作业失败" tabindex="-1">抄作业失败 <a class="header-anchor" href="#抄作业失败" aria-label="Permalink to “抄作业失败”">​</a></h3><ul><li><code>0s</code> 结束：通常是作业未激活</li><li><code>10~20s</code> 左右结束：通常是开始页面不对，未识别到关键 UI</li><li>导入后无法连接或提示资源加载失败：优先同时检查 MaaYuan 版本与作业生成时间</li></ul><h3 id="打到第七回合自动结束" tabindex="-1">打到第七回合自动结束 <a class="header-anchor" href="#打到第七回合自动结束" aria-label="Permalink to “打到第七回合自动结束”">​</a></h3><ul><li>检查是否勾选了“抄完几回合后自动停止”</li><li>调整分辨率到 <code>720 × 1280</code></li><li>不行的话改为“战斗中开始抄作业”模式</li></ul><h2 id="七、其他问题" tabindex="-1">七、其他问题 <a class="header-anchor" href="#七、其他问题" aria-label="Permalink to “七、其他问题”">​</a></h2><h3 id="管理员权限说明" tabindex="-1">管理员权限说明 <a class="header-anchor" href="#管理员权限说明" aria-label="Permalink to “管理员权限说明”">​</a></h3><p>通常不需要管理员权限，但以下情况除外：</p><ul><li>模拟器以管理员身份运行</li><li>安装路径没有写入权限</li><li>某些自动检测或关闭模拟器操作被系统拦截</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果你已经清理过运行库、分辨率、ADB、作业目录这些高频问题，仍然无法解决，请按 <a href="./../Manual/Feedback.html">反馈方式</a> 中的步骤导出 <code>maa.log</code> 后再反馈。</p></div>`,57))])}const x=s(o,[["render",k]]);export{f as __pageData,x as default};
